// ------------------------------------------------------
const $ = (s, r = document) => r.querySelector(s);
const el = (h) => { const t = document.createElement("template"); t.innerHTML = h.trim(); return t.content.firstChild; };
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const dlg = $("#dlg");

function openSetup(item) {
  $("#dTitle").textContent = item.title || item.name;
  $("#dDesc").textContent = item.desc || "Copy this and paste it into your AI.";
  $("#dBody").textContent = item.setup || `Get it from the source: ${item.source}`;
  dlg.showModal();
}
$("#copy").onclick = async (e) => {
  try { await navigator.clipboard.writeText($("#dBody").textContent); e.target.textContent = "Copied ✓"; }
  catch { e.target.textContent = "Select and copy manually"; }
  setTimeout(() => (e.target.textContent = "Copy setup"), 1500);
};
$("#close").onclick = () => dlg.close();

const agents = $("#agents");
let allAgents = [];
function renderAgents(q = "") {
  const term = q.trim().toLowerCase();
  const list = allAgents.filter((a) => (a.name + " " + a.desc).toLowerCase().includes(term));
  agents.replaceChildren(...list.map((a) => {
    const c = el(`<button class="card"><code>${esc(a.name)}</code><p>${esc(a.desc)}</p></button>`);
    c.onclick = () => openSetup(a);
    return c;
  }));
  $("#count").textContent = `${list.length} free agent${list.length === 1 ? "" : "s"}. No sign-up.`;
}
fetch("content.json")
  .then((r) => { if (!r.ok) throw new Error(r.status); return r.json(); })
  .then((d) => { allAgents = d.agents; $("#agentCount").textContent = allAgents.length; renderAgents(); })
  .catch((err) => { console.error("content.json load failed", err); $("#count").textContent = "Couldn't load agents. Please refresh."; });
$("#q").oninput = (e) => renderAgents(e.target.value);

const wf = $("#workflows");
CONFIG.workflows.forEach((w) => {
  const r = el(`<div class="row"><div><b>${esc(w.title)}</b><br><small>${esc(w.tag)}</small></div><button class="btn ghost">Get the setup</button></div>`);
  $("button", r).onclick = () => openSetup(w); wf.append(r);
});
CONFIG.tools.forEach((t) => $("#toolList").append(el(`<div class="row"><div><b>${esc(t.name)}</b><br><small>${esc(t.why)}</small></div>${t.url ? `<a class="btn ghost" href="${esc(t.url)}" target="_blank" rel="noopener">Visit →</a>` : ""}</div>`)));
CONFIG.socials.forEach((s) => $("#socials").append(el(`<div class="row"><div><b>${esc(s.name)}</b> <small>${esc(s.handle)}</small></div><a class="btn ghost" href="${esc(s.url)}" target="_blank" rel="noopener">Open</a></div>`)));
fetch("videos.json")
  .then((r) => { if (!r.ok) throw new Error(r.status); return r.json(); })
  .then((vs) => $("#videoGrid").replaceChildren(...vs.map((v) =>
    el(`<a href="https://www.youtube.com/watch?v=${encodeURIComponent(v.id)}" target="_blank" rel="noopener"><img loading="lazy" src="https://i.ytimg.com/vi/${encodeURIComponent(v.id)}/mqdefault.jpg" alt="">${esc(v.title)}</a>`))))
  .catch((err) => console.error("videos.json load failed", err));
// Motion: pointer parallax on the hero, 3D tilt on agent cards, scroll reveals. Skipped for reduced-motion users.
if (!matchMedia("(prefers-reduced-motion: reduce)").matches) {
  const hero = $(".hero"), stage = $(".stage");
  hero.addEventListener("pointermove", (e) => {
    const r = hero.getBoundingClientRect();
    stage.style.setProperty("--ry", `${((e.clientX - r.left) / r.width - 0.5) * 14}deg`);
    stage.style.setProperty("--rx", `${-((e.clientY - r.top) / r.height - 0.5) * 10}deg`);
  });
  hero.addEventListener("pointerleave", () => { stage.style.removeProperty("--rx"); stage.style.removeProperty("--ry"); });

  agents.addEventListener("pointermove", (e) => {
    const c = e.target.closest(".card"); if (!c) return;
    const r = c.getBoundingClientRect();
    c.style.transform = `perspective(700px) rotateY(${((e.clientX - r.left) / r.width - 0.5) * 10}deg) rotateX(${-((e.clientY - r.top) / r.height - 0.5) * 10}deg)`;
  });
  agents.addEventListener("pointerout", (e) => { const c = e.target.closest(".card"); if (c) c.style.transform = ""; });

  const io = new IntersectionObserver((entries) => entries.forEach((en) => { if (en.isIntersecting) { en.target.classList.add("in"); io.unobserve(en.target); } }), { threshold: 0.1 });
  document.querySelectorAll("section:not(.hero) > .wrap").forEach((n) => { n.classList.add("reveal"); io.observe(n); });
}
$("#yr").textContent = new Date().getFullYear();

// Turnstile error callback: show why the check failed instead of failing silently
window.tsError = (code) => {
  console.error("turnstile error", code);
  document.querySelectorAll(".msg").forEach((m) => (m.textContent = `Spam check could not load (error ${code}). Refresh, or turn off ad-blockers for this site.`));
};

document.querySelectorAll("form[data-form]").forEach((f) => (f.onsubmit = async (e) => {
  e.preventDefault();
  const out = $(".msg", f) || $(".msg", f.parentElement);
  const data = Object.fromEntries(new FormData(f));
  if (!data["cf-turnstile-response"]) { out.textContent = "Please wait a moment for the spam check to finish, then try again."; return; }
  try {
    const r = await fetch(`/api/${f.dataset.form}`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(data) });
    const res = await r.json().catch(() => ({}));
    if (window.turnstile) turnstile.reset(f.querySelector(".cf-turnstile")); // tokens are single-use
    if (!r.ok) { out.textContent = res.error || "Something went wrong. Please try again."; return; }
    f.reset(); out.textContent = "Thanks, you're in ✓";
  } catch (err) { console.error("form submit failed", err); out.textContent = "Network error. Please try again."; }
}));
